package com.xato.record;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.ServiceInfo;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.net.Uri;import android.provider.*;import android.view.*;import android.widget.*;import java.io.*;
public class RecordService extends Service {
 public static volatile boolean running=false; MediaProjection projection; MediaRecorder recorder; VirtualDisplay display; Uri output; ParcelFileDescriptor fd; boolean started,paused,ending; WindowManager wm; LinearLayout bubble; LinearLayout actions; Handler handler=new Handler(Looper.getMainLooper());
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i==null){stopSelf();return START_NOT_STICKY;}String a=i.getAction();if("STOP".equals(a)){finish();return START_NOT_STICKY;}if("PAUSE".equals(a)){toggle();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;
 try{boolean mic=i.getBooleanExtra("mic",false);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("record","Grabación de pantalla",NotificationManager.IMPORTANCE_LOW));int types=ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION|(mic?ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE:0);startForeground(1,notification(false),types);running=true;
 projection=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(-1,(Intent)i.getParcelableExtra("data"));projection.registerCallback(new MediaProjection.Callback(){public void onStop(){finish();}},handler);
 android.content.SharedPreferences p=getSharedPreferences("settings",0);WindowManager manager=getSystemService(WindowManager.class);android.util.DisplayMetrics metrics=new android.util.DisplayMetrics();manager.getDefaultDisplay().getRealMetrics(metrics);int shortSide=new int[]{480,720,1080}[p.getInt("quality",1)];double scale=Math.min(1.0,shortSide/(double)Math.min(metrics.widthPixels,metrics.heightPixels));int w=((int)(metrics.widthPixels*scale)/2)*2,h=((int)(metrics.heightPixels*scale)/2)*2;
 ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"XatoRecord_"+new java.text.SimpleDateFormat("yyyyMMdd_HHmmss",java.util.Locale.US).format(new java.util.Date())+".mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");values.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/XatoRecord");values.put(MediaStore.Video.Media.IS_PENDING,1);output=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(output==null)throw new IOException("No se pudo crear el vídeo");fd=getContentResolver().openFileDescriptor(output,"w");
 recorder=new MediaRecorder();if(mic)recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setVideoSource(MediaRecorder.VideoSource.SURFACE);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setOutputFile(fd.getFileDescriptor());recorder.setVideoEncoder(MediaRecorder.VideoEncoder.H264);recorder.setVideoSize(w,h);recorder.setVideoFrameRate(new int[]{24,30,60}[p.getInt("fps",1)]);recorder.setVideoEncodingBitRate(new int[]{2000000,4000000,8000000,12000000}[p.getInt("bitrate",1)]);if(mic){recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(44100);recorder.setAudioEncodingBitRate(128000);}recorder.setOnErrorListener((r,what,extra)->finish());recorder.prepare();display=projection.createVirtualDisplay("XatoRecord",w,h,metrics.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,recorder.getSurface(),null,handler);recorder.start();started=true;showBubble();Toast.makeText(this,"Grabación iniciada",0).show();
 }catch(Exception e){Toast.makeText(this,"No se pudo grabar. Prueba 720p / 30 FPS. "+e.getClass().getSimpleName(),1).show();finish();}return START_NOT_STICKY;}
 Notification notification(boolean pause){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,RecordService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE);PendingIntent toggle=PendingIntent.getService(this,2,new Intent(this,RecordService.class).setAction("PAUSE"),PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"record").setSmallIcon(com.xato.record.R.drawable.ic_record).setContentTitle("XatoRecord Pantalla").setContentText(pause?"Grabación pausada":"Grabando pantalla").setContentIntent(open).setOngoing(true).addAction(0,pause?"Reanudar":"Pausar",toggle).addAction(0,"Detener",stop).build();}
 void toggle(){if(!started)return;try{if(paused)recorder.resume();else recorder.pause();paused=!paused;getSystemService(NotificationManager.class).notify(1,notification(paused));if(actions!=null)((Button)actions.getChildAt(0)).setText(paused?"▶":"Ⅱ");}catch(Exception e){finish();}}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 void showBubble(){if(!Settings.canDrawOverlays(this))return;try{wm=getSystemService(WindowManager.class);android.content.SharedPreferences p=getSharedPreferences("settings",0);bubble=new LinearLayout(this);bubble.setOrientation(1);ImageView icon=new ImageView(this);File f=new File(getFilesDir(),"bubble.png");if(f.exists())icon.setImageBitmap(BitmapFactory.decodeFile(f.toString()));else icon.setImageResource(R.drawable.ic_record);icon.setScaleType(ImageView.ScaleType.CENTER_CROP);int size=dp(new int[]{40,52,64}[p.getInt("size",1)]);bubble.addView(icon,new LinearLayout.LayoutParams(size,size));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(28,30,40));bg.setCornerRadius(dp(20));bubble.setBackground(bg);bubble.setAlpha(new float[]{.5f,.75f,1f}[p.getInt("alpha",2)]);
 actions=new LinearLayout(this);Button pause=new Button(this);pause.setText("Ⅱ");pause.setContentDescription("Pausar o reanudar");pause.setOnClickListener(v->toggle());Button stop=new Button(this);stop.setText("■");stop.setContentDescription("Detener y guardar");stop.setOnClickListener(v->finish());actions.addView(pause,new LinearLayout.LayoutParams(dp(56),dp(48)));actions.addView(stop,new LinearLayout.LayoutParams(dp(56),dp(48)));actions.setVisibility(View.GONE);bubble.addView(actions);
 WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.LEFT;lp.x=dp(12);lp.y=dp(160);icon.setOnTouchListener(new View.OnTouchListener(){float x,y;int bx,by;boolean moved;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){x=e.getRawX();y=e.getRawY();bx=lp.x;by=lp.y;moved=false;return true;}if(e.getAction()==2){float dx=e.getRawX()-x,dy=e.getRawY()-y;if(Math.abs(dx)+Math.abs(dy)>dp(6))moved=true;android.util.DisplayMetrics m=getResources().getDisplayMetrics();lp.x=Math.max(0,Math.min(m.widthPixels-size,bx+(int)dx));lp.y=Math.max(0,Math.min(m.heightPixels-size,by+(int)dy));wm.updateViewLayout(bubble,lp);return true;}if(e.getAction()==1){if(!moved)actions.setVisibility(actions.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);return true;}return false;}});wm.addView(bubble,lp);
 }catch(Exception e){bubble=null;Toast.makeText(this,"Usa los controles de la notificación",0).show();}}
 void finish(){if(ending)return;ending=true;boolean ok=false;if(recorder!=null){try{if(started){recorder.stop();ok=true;}}catch(Exception ignored){}try{recorder.release();}catch(Exception ignored){}recorder=null;}started=false;if(display!=null){display.release();display=null;}if(projection!=null){MediaProjection pr=projection;projection=null;pr.stop();}if(fd!=null){try{fd.close();}catch(Exception ignored){}fd=null;}if(output!=null){try{if(ok){ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.IS_PENDING,0);getContentResolver().update(output,v,null,null);}else getContentResolver().delete(output,null,null);}catch(Exception ignored){}output=null;}if(bubble!=null&&wm!=null){try{wm.removeView(bubble);}catch(Exception ignored){}bubble=null;}running=false;stopForeground(STOP_FOREGROUND_REMOVE);if(ok)Toast.makeText(this,"Vídeo guardado en Movies/XatoRecord",1).show();stopSelf();}
 public void onDestroy(){finish();super.onDestroy();}
 public void onTaskRemoved(Intent root){/* Sigue grabando; detener desde la notificación. */}
}
